let btnGerar=document.getElementById("generato"),numeroBase=document.getElementById("numBase"),numeroContador=document.getElementById("numContador");function gerarTabuada(a){var n=document.getElementById("tabuada");for(let e=1;e<=parseInt(numeroContador.value);e++){var t=a*e,o=document.createElement("li");o.textContent=`${a} x ${e} = `+t,n.appendChild(o)}}btnGerar.addEventListener("click",function(){""==numeroBase.value||""==numeroContador.value?alert("Os campos são obrigatório para essa operação"):(gerarTabuada(parseInt(numeroBase.value)),numeroBase.value="",numeroContador.value="")});